    (h : accepts S S' check ((r, (i.castSucc, τ)), x, y) ((r, (i.castSucc, τ')), x', y') u v
      = true) :
    CL.accepts hm (q1 S i τ y) (q1 S i τ' y') (ans1 u) (ans1 v) = true := by sorry

theorem MIPRE.AnswerReduction.cl_accepts_of_accepts6 {i : Fin 6} (hi : (i : ℕ) = 5) (τ τ' : Ty) {x x' : X}
    {y y' : Coord P → F} {u v : Ans P F}
    (h : accepts S S' check ((.oracle, (i, τ)), x, y) ((.oracle, (i, τ')), x', y') u v = true) :
    CL.accepts hm' (q6 S' τ y) (q6 S' τ' y') (ans6 u) (ans6 v) = true := by sorry

theorem MIPRE.AnswerReduction.Pcp.comps_marginal (t : Ty) {j : ℕ} (hj : 1 ≤ j) (x : Coord P → F) :
    comps P ((((regsAt P o sz c h).pres S t).truncate j).eval x) =
      (if 3 ≤ j then placeV o (Regs.ptMap S t (seedsOf P x c)
          (dirPart sz S t (seedsOf P x c) (sliceV o sz h (dirOf6 P x))) (sliceV o sz h (ptOf6 P x)))
        else 0,
       if 2 ≤ j then placeV o (dirPart sz S t (seedsOf P x c) (sliceV o sz h (dirOf6 P x)))
        else 0,
       seedPart c t (seedsOf P x c)) := by sorry

